" y=\"72\" width=\"26\" height=\"26\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"37.0\" y=\"88.0\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">12</text><rect x=\"50\" y=\"72\" width=\"26\" height=\"26\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"63.0\" y=\"88.0\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">10</text><rect x=\"76\" y=\"72\" width=\"26\" height=\"26\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"89.0\" y=\"88.0\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">11</text><text x=\"63\" y=\"108\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">salt pixel: 200</text><line x1=\"110\" y1=\"58\" x2=\"138\" y2=\"58\" stroke=\"#000000\" stroke-width=\"1.2\" marker-end=\"url(#arr-3116)\"/><text x=\"184\" y=\"30\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">sorted:</text><text x=\"184\" y=\"44\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">9 10 10 11</text><text x=\"184\" y=\"56\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">11 12 12 13 200</text><text x=\"184\" y=\"78\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">median = 11</text><text x=\"184\" y=\"98\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">mean = 288/9 = 32</text><text x=\"184\" y=\"114\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">(skewed by 200)</text></svg>",
    "drawingCaption": "The outlier 200 drags the mean to 32 but leaves the median at 11",
