    "drawingSvg": "<svg viewBox=\"0 0 240 145\" class=\"w-full h-full\"><defs><marker id=\"arr-3126\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M 0 1.5 L 8 5 L 0 8.5 z\" fill=\"#000000\"/></marker></defs><line x1=\"24\" y1=\"125\" x2=\"226\" y2=\"125\" stroke=\"#000000\" stroke-width=\"1.2\" marker-end=\"url(#arr-3126)\"/><line x1=\"24\" y1=\"125\" x2=\"24\" y2=\"14\" stroke=\"#000000\" stroke-width=\"1.2\" marker-end=\"url(#arr-3126)\"/><line x1=\"24.0\" y1=\"37.29915170003807\" x2=\"174.0\" y2=\"106.29915170003807\" stroke=\"#000000\" stroke-width=\"1.2\"/><circle cx=\"124.0\" cy=\"83.29915170003807\" r=\"4\" fill=\"#000000\" stroke=\"#000000\" stroke-width=\"1.2\"/><text x=\"24\" y=\"138\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">1</text><text x=\"74\" y=\"138\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">10</text><text x=\"124\" y=\"138\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">100</text><text x=\"174\" y=\"138\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">1000</text><text x=\"210\" y=\"138\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">MSE</text><text x=\"132.0\" y=\"75.29915170003807\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">28.13 dB</text><text x=\"30\" y=\"20\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">PSNR (dB)</text><text x=\"160\" y=\"40\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">\u221210 dB per decade</text></svg>",
